#!/usr/bin/env bash
#
# Creates the development database layout: roles, schemas, the real Laravel
# `site` tables (dev/db/20-site-schema.sql, generated by
# scripts/site-schema-snapshot.sh) with demo data, the real `api_read` views
# from docs/contract/views.sql, then the production roles of
# deploy/sql/phase-1.sql. Used by `docker compose` (on first start) and by CI.
#
# The `game` tables come from the migrations: `pulsars-api migrate` with
# DATABASE_MIGRATION_URL, or the integration tests with
# TEST_MIGRATION_DATABASE_URL.
#
# Connects with the standard libpq variables (PGHOST, PGPORT, PGUSER,
# PGPASSWORD) as a superuser, to the database named by PGDATABASE (default
# `pulsars`), which must exist and be empty.
#
#     PGHOST=127.0.0.1 PGUSER=postgres PGPASSWORD=postgres ./scripts/dev-db-init.sh

set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
export PGDATABASE="${PGDATABASE:-pulsars}"

run() {
    echo "==> $1"
    psql --no-psqlrc --quiet --set ON_ERROR_STOP=1 --file "$1"
}

run "$root/dev/db/10-roles.sql"
run "$root/dev/db/20-site-schema.sql"
run "$root/dev/db/30-demo-data.sql"

echo "==> $root/docs/contract/views.sql (as pulsars_site)"
{
    echo "SET ROLE pulsars_site;"
    cat "$root/docs/contract/views.sql"
} | psql --no-psqlrc --quiet --set ON_ERROR_STOP=1

# The production layout: pulsars_owner owns everything, pulsars_migrate runs
# the migrations, the service roles have no DDL right.
echo "==> $root/deploy/sql/phase-1.sql"
psql --no-psqlrc --quiet --set ON_ERROR_STOP=1 --set mdp_migrate=pulsars_migrate_dev \
    --file "$root/deploy/sql/phase-1.sql"

where="${PGHOST:-localhost}:${PGPORT:-5432}/${PGDATABASE}"
echo "Done. The API connects as: postgres://pulsars_api:pulsars_api_dev@$where"
echo "Migrations run as:         postgres://pulsars_migrate:pulsars_migrate_dev@$where"
